def groups = [['key':'ENVELOPE','identifier':'FSAE2027:VP:obligation:ENVELOPE','title':'Accommodate and protect the complete driver population','model_keys':['accommodate','rollover'],'statement':'Accommodate the 5th-percentile female through 95th-percentile male population in seating, controls and driver equipment. Keep the driver\'s head and hands clear of the ground in every rollover orientation. Event-site anthropometry is an external input that has not yet been selected.','conditions_and_alternatives':['All team drivers and the prescribed anthropometric range; no single nominal driver is substituted.'],'verification_obligation':'Review an approved anthropometric dataset and every driver/equipment combination. Check reach and occupant geometry and sweep all rollover orientations, including restrained head and hand envelopes.','unresolved_decisions':['Driver dataset, team driver measurements, equipment and adjustable seating/control geometry TBD.'],'dependent_source_rules':['F.1.13'],'source_clauses':[['V.2.1.1:p001','0245991663b64dbbb3a05ff99ccb1740165cc953ac38e14e7d47a9d7dd297437'],['V.2.1.1:p002','ca83532be64364678f267fcb22da0b9fca998158e92d47c53935d4f0eeeccf22'],['V.2.1.1:p003','b3db2892495b776bcd89125668341cb6cd9e8d56be0f8779367fa65af637faa5'],['V.2.1.2:p001','3ba9ef6e0be4e887d5627507f82656f65228ea0ed1bb30b024d85f4351ef5137']]],['key':'PRIMARY-MATERIAL','identifier':'FSAE2027:VP:obligation:PRIMARY-MATERIAL','title':'Choose and substantiate the primary structure','model_keys':['loadpath','side','rollover'],'statement':'The primary structure may use steel tubing/material, an allowed alternative tubing material, composite material or a combination. A mixed tube-frame/monocoque/tube/composite design must satisfy the relevant material rules, applicable structural equivalence and connection requirements. No construction is selected by this candidate model.','conditions_and_alternatives':['Tube, monocoque and hybrid alternatives remain unresolved.','The source F.5.1.1 and F.3.2.1 references to F.3.4.4 are retained as published; F.3.5 actually contains the aluminum provisions. Seek official clarification rather than silently changing the reference.'],'verification_obligation':'Select construction in the structural equivalence submission; enumerate every material and transition joint and substantiate equivalence, fastening, bonding and monocoque attachments under the applicable referenced clauses.','unresolved_decisions':['Chassis type, material grades, laminates, connections and equivalence evidence TBD.'],'dependent_source_rules':['F.2.2.2','F.4','F.5.4','F.5.5','F.7.8'],'source_clauses':[['F.5.1.1:p001','e84975e4ce202a4de6673e5c4c1976a3bd565d694f0104f4c5b94ddfd021b674'],['F.5.1.1:p002','e5b1001ff18a09bdb1fdae82eed610824c57ab7244b3278ce01383fca50ec9c3'],['F.5.1.1:p003','2c0c3f809fae870f2389f721292f69642bac011505a9f43a7c10d00756312803'],['F.5.1.1:p004','a79ea188179ca2ddc6d71254f14454fc5d85bfd5fb96e4317bf5148673bc2de4'],['F.5.1.2:p001','82f58656a4cf5a1769523397463e2362c5497dcd3219fbf432ba25d522eae20d'],['F.5.1.2:p002','b482195a81d58baedb0f7f6041bac6b36e6711f93cc2339bcbf60c08f56be05c'],['F.5.1.2:p003','91d9d9f253a1f95ae8d2a8093a6b8a15953ad1c188f19f5d25f0469de8418eb7'],['F.5.1.2:p004','dca022ae78312a37b328b8a04ed7d94cc8e630480c052ca5f4c4695b52f77143']]],['key':'TUBE-APPLICATION','identifier':'FSAE2027:VP:obligation:TUBE-APPLICATION','title':'Apply tubing classes and material restrictions','model_keys':['loadpath','rollover','side','restrain','front'],'statement':'Assign steel tube classes by application: A for front hoop, main hoop and shoulder-harness mounting bar; B for front bulkhead, front-hoop bracing, side-impact structure, main-hoop bracing, harness attachment and battery mounting/protection; C for front-bulkhead supports, main-hoop brace supports, shoulder-bar bracing, component protection and structural tubing; D for bent upper side-impact members. Aluminum is prohibited for the main hoop, main-hoop bracing and shoulder-harness mounting bar; it is permitted conditionally for the other listed applications. Tubing below the structural class is nonstructural and cannot be credited for rule compliance.','conditions_and_alternatives':['All rows of the application table are preserved as constraints, including battery protection which is only an interface to this slice.'],'verification_obligation':'Build a member/application/material matrix, confirm each required class and prohibited aluminum application, and exclude nonstructural members from the equivalence/load-path assessment.','unresolved_decisions':['Actual member sizes and application/material matrix TBD.'],'dependent_source_rules':['F.3.4','F.3.5'],'source_clauses':[['F.3.2.1:p001','a84f67827a9cfce354e1f63032fe6082b789c54f9f70f19f20430e6e2e0e8979'],['F.3.2.1:p002','5e12f450b0d056b0377565df64d5a49ee3852d29d39b4ea5cc05ccac0fd360f7'],['F.3.2.1:p003','e9ac2871c070c0edfd3d9b43057c88fd0abddd0cc0d6fefb16e7d4c107610a33'],['F.3.2.1:p004','373f997494e34b67a49fe3ebedff826cfa7a64ec74df84f5fc99891bfa0afe53'],['F.3.2.1:p005','bb3dd733437358fdfa8e34643edf2cd454a33d73d3dbfd6cd05d3e7d0c9f7b33'],['F.3.2.1:p006','870611d2f1be88834f043bf580bc9cc76fba2c982d9153d7b452640e143962df'],['F.3.2.1:p007','579257e3d20a2997b0a57db13f183a853793a2ea1709827ca34502c49f990ff8'],['F.3.2.1:p008','b80de831a131b19bca1ef2e4df6d53ead49e99093bb14dd533911dd04e23923c'],['F.3.2.1:p009','cb311ccea9fb70bb1d377263dd47a7c6241a4b8cc86c71a47823a10a9fef3c86'],['F.3.2.1:p010','7c442bc09d1685683051c6b1b327347a8ca7462b5e7b055f9d74ae2f298f77db'],['F.3.2.1:p011','a2b62ef86ad5e71cd4009404baf09a7a1c47bb53f5ea0e777f9f01ee9284ae65'],['F.3.2.1:p012','334a52812e4f10a666a975c8a02d9607554918e7feee37de4235b94f1ea50b1f'],['F.3.2.1:p013','beaea8b97c58ff430a16692dc96ffb7a68f1d0881afedf2eb1d60196d2ae95f2'],['F.3.2.1:p014','5493bf4209436785060247560275d1166a9aa49e5f64837644735746739142b2'],['F.3.2.1:p015','75663b3cc982368af37645c0ed6cd2fb1adb30ca4be22b69dd0dc9141116f2cb'],['F.3.2.1:p016','9d2bea6741fd